/***************************************************************************************************** 
 *
 * Given a sorted linked list, delete all nodes that have duplicate numbers, leaving only distinct 
 * numbers from the original list.
 * 
 * Return the linked list sorted as well.
 * 
 * Example 1:
 * 
 * Input: 1->2->3->3->4->4->5
 * Output: 1->2->5
 * 
 * Example 2:
 * 
 * Input: 1->1->1->2->3
 * Output: 2->3
 ******************************************************************************************************/

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode deleteDuplicates(ListNode head) {
        if (head == null) {
            return null;
        }

        var dummy = new ListNode(-1, head);
        // 初始时 pre.next 指向的就是 cur，需要一直保持下去
        var pre = dummy;
        var cur = dummy.next;

        while (cur != null) {
            if (cur.next != null && cur.val == cur.next.val) {
                var val = cur.val;
                while (cur != null && cur.val == val) {
                    cur = cur.next;
                }

                // System.out.println(cur != null ? cur.val : -1);
                // cur is null or cur.val != val
                // 这里 pre 其实没有移动，把重复的前 k - 1 个跳过了，取最后一个
                pre.next = cur;
            } else {
                pre = cur;
                cur = cur.next;
            }
        }

        return dummy.next;
    }
}

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {

        if(head == NULL || head -> next == NULL)
            return head;

        unordered_map <int, int>m;

        ListNode* itit = (0, head);
        ListNode* it = head;
        ListNode* ans = NULL;

        int count = 0;

        while(head != NULL){

            m[head -> val]++;
            head = head -> next;

        }

        while(it != NULL){

            if(m[it -> val] == 1){

                count++;

                if(count == 1){

                    ans = it;
                    itit = it;

                    it = it -> next;
                    continue;

                }

                itit -> next = it;
                itit = itit -> next;

            }

            it = it -> next;

            if(it == NULL)
                itit -> next = NULL;

        }

        return ans;
    }
};

